    );

    let parent_name = [(
        "src/lib.rs",
        "fn start() {}\nmod child {\n    pub fn g() {\n        start();\n    }\n}\n",
        Rust,
    )];
    let (cg, _) = build(&parent_name);
    assert!(
        cg.resolve_call_site(&site_in(&cg, "g", "start")).is_empty(),
