    );

    let shadowed = [(
        "src/lib.rs",
        "fn process() {}\npub fn g() {\n    let process = || {};\n    process();\n}\n",
        Rust,
    )];
    let (cg, _) = build(&shadowed);
    assert!(
        cg.resolve_call_site(&site_in(&cg, "g", "process"))
            .is_empty(),
        "a local let binding shadows the free fn and must not mint an edge"
    );

    let private_import = [
        (
