#[test]
fn scope_graph_singleton_unresolved_owner_recovers_to_exact_not_drop() {
    use prism::languages::Language::Rust;
    // Negative/edge case for the fail-open floor added by Task 5: a bare
    // `(owner, method)` pool that is a SINGLETON (only one `Missing::make` in the
    // whole repo), where the owner path still does NOT resolve through the graph
    // (`Missing` is neither defined nor imported in lib.rs, so ②B's directness
    // check has nothing to prove against). Pre-Task-5, the scope branch's only
    // move was `rust_scope_graph_resolution` (resolve-or-drop): an unresolved
    // `Missing::make` qualified path dropped outright (`UnknownName`), same as the
    // collision fixture below minus the demote. Task 5's fail-open now routes
    // this to `owner_lookup_in_modules`, which returns Exact for a true
    // singleton — this is the drop -> Exact recall fix for the *uncollided* case
    // (the sibling `scope_graph_unresolved_owner_path_keeps_full_pool_not_drop`
    // test deliberately uses TWO colliding defs so it can't be vacuously Exact;
    // this test pins the complementary singleton shape that test's own comment
    // flags as reaching a different — and previously untested — branch).
    let sources = [
        (
            "src/lib.rs",
            "mod other;\npub fn drive() {\n    Missing::make();\n}\n",
            Rust,
        ),
        (
            "src/other.rs",
            "pub struct Missing;\nimpl Missing {\n    pub fn make(&self) {}\n}\n",
            Rust,
        ),
    ];
    let (cg, _) = build(&sources);
    assert_eq!(
        cg.methods
            .get(&("Missing".to_string(), "make".to_string()))
            .map(|v| v.len()),
        Some(1),
        "the bare owner key must be a true singleton (no collision) to pin the \
         fail-open's Exact branch, not its NameOnly demote branch",
    );
    let out = cg.resolve_call_site_full(&site_in(&cg, "drive", "Missing::make"));
    assert_eq!(
        out.drop, None,
        "a singleton bare pool must recover to Exact, not drop"
    );
    assert_eq!(out.resolved.len(), 1);
    assert_eq!(out.resolved[0].target.file, "src/other.rs");
    assert_eq!(out.resolved[0].confidence, ResolutionConfidence::Exact);
    assert_eq!(out.resolved[0].kind, ResolutionKind::QualifiedOwner);
}

